def deep_value(dictionary, path):
    def match_segment(segment, keys):
        if segment == '*':
            return keys
        if segment in keys:
            return [segment]
        return []

    def traverse(current_dict, remaining_path, results):
        if not remaining_path:
            # We've reached a leaf; if current_dict is not a dict, it's a value
            if not isinstance(current_dict, dict):
                results.append(current_dict)
            return

        # Split the first segment of the path
        first_segment, *rest = remaining_path.split('.', 1)

        # Find all keys that match the first segment
        matching_keys = match_segment(first_segment, current_dict.keys())

        for key in matching_keys:
            next_dict = current_dict[key]
            if isinstance(next_dict, dict):
                traverse(next_dict, rest, results)
            else:
                # If we hit a non-dict before consuming the full path, it's not a match
                pass

    results = []
    if not isinstance(dictionary, dict):
        return results

    traverse(dictionary, path, results)
    return results
