import random

def findKthSmallest(nums, k):
    """
    Finds the k-th smallest element in an unsorted list of integers.
    Uses the Quickselect algorithm (average O(n) time complexity).
    Handles duplicates correctly.

    Parameters:
    nums (List[int]): List of integers.
    k (int): The position (1-based) of the smallest element to find.

    Returns:
    int: The k-th smallest element.
    """
    if not nums or k < 1 or k > len(nums):
        raise ValueError("Invalid input for k or empty array.")

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        # Move pivot to end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left
        for i in range(left, right):
            if nums[i] < pivot_value:
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1
        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left, right, k_smallest):
        if left == right:
            return nums[left]

        # Choose a random pivot to avoid worst-case scenarios
        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_smallest == pivot_index:
            return nums[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    # Convert 1-based k to 0-based index
    return quickselect(0, len(nums) - 1, k - 1)
